const message = $json || {};

const headerList = message.payload?.headers || message.headers || [];
const headerMap = {};
if (Array.isArray(headerList)) {
  for (const header of headerList) {
    if (header?.name) headerMap[String(header.name).toLowerCase()] = header.value || '';
  }
}

const addressFrom = (value) => {
  if (!value) return '';
  if (typeof value === 'string') {
    const match = value.match(/<([^>]+)>/) || value.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    return match ? String(match[1] || match[0]).toLowerCase().trim() : value.toLowerCase().trim();
  }
  if (Array.isArray(value?.value) && value.value[0]) {
    return String(value.value[0].address || value.value[0].email || '').toLowerCase().trim();
  }
  return String(value.address || value.email || '').toLowerCase().trim();
};

const stripHtml = (value) => String(value || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'");

const fromEmail = addressFrom(message.from || headerMap.from);
const toEmail = addressFrom(message.to || headerMap.to);
const subject = String(message.subject || headerMap.subject || '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 500);

let body = String(
  message.textPlain
  || message.text
  || message.snippet
  || stripHtml(message.textHtml || message.html || '')
  || ''
).replace(/\r/g, '');

body = body
  .split(/\nOn .{0,300}wrote:\s*\n/i)[0]
  .split(/\nFrom:\s*.{0,500}\n/i)[0]
  .split(/\n-{2,}\s*Original Message\s*-{2,}/i)[0]
  .split('\n')
  .filter((line) => !/^\s*>/.test(line))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 8000);

const autoHeader = String(
  headerMap['auto-submitted']
  || headerMap['x-autoreply']
  || headerMap['x-autorespond']
  || ''
).toLowerCase();

const possibleDeliveryFailure =
  /mailer-daemon|postmaster/i.test(fromEmail)
  || /undeliverable|delivery (?:status notification|failure|failed)|mail delivery|returned mail|address not found|message blocked|bounced/i.test(subject + '\n' + body);

const rawTime = message.internalDate || message.date || headerMap.date || '';
const parsedTime = Number(rawTime) > 1000000000000
  ? new Date(Number(rawTime))
  : new Date(rawTime || Date.now());

return {
  json: {
    incoming_message_id: String(message.id || message.messageId || ''),
    gmail_thread_id: String(message.threadId || message.thread_id || ''),
    from_email: fromEmail,
    to_email: toEmail,
    reply_subject: subject,
    reply_text: body,
    reply_received_at: Number.isNaN(parsedTime.getTime()) ? new Date().toISOString() : parsedTime.toISOString(),
    gmail_label_ids: message.labelIds || [],
    possible_delivery_failure: possibleDeliveryFailure,
    possible_automated_reply:
      possibleDeliveryFailure
      || Boolean(autoHeader && autoHeader !== 'no')
      || /no-?reply/i.test(fromEmail)
      || /automatic reply|auto.?reply|out of office/i.test(subject)
  }
};

const replies = $('Normalize Incoming Reply').all(0, $runIndex);
const reply = replies[$itemIndex]?.json || replies[0]?.json || {};
const lead = $json || {};

return {
  json: {
    ...lead,
    incoming_reply: reply
  }
};

const data = $json || {};
const reply = data.incoming_reply || {};

const prompt = `Classify the latest reply to a CodeNativeX outreach email.

ALLOWED INTENTS
- meeting_request
- pricing_question
- interested
- information_request
- not_interested
- unsubscribe
- out_of_office
- wrong_person
- delivery_failed
- unclear

RULES
- Classify only the new reply text. Quoted history has already been removed.
- An explicit request to stop, unsubscribe, remove the address, or never contact again is "unsubscribe".
- A polite rejection or statement that the service is not needed is "not_interested".
- Asking for a video, demo, walkthrough, screen share, call, calendar, date, time, or availability is "meeting_request".
- Asking about price, quote, rates, budget, or cost is "pricing_question".
- Asking for a portfolio, details, process, case study, or more information is "information_request".
- Positive interest without a specific request is "interested".
- Automatic vacation or absence messages are "out_of_office".
- Delivery failures, bounced mail, invalid recipients, and blocked delivery are "delivery_failed".
- Saying this is the wrong person or company is "wrong_person".
- Do not invent intent. Use "unclear" when uncertain.
- Return strict JSON only.

COMPANY: ${data.company_name || ''}
CONTACT: ${data.contact_name || ''}
ORIGINAL OUTREACH SUBJECT: ${data.outreach_subject || ''}
REPLY FROM: ${reply.from_email || ''}
REPLY SUBJECT: ${reply.reply_subject || ''}
AUTOMATED SIGNAL: ${Boolean(reply.possible_automated_reply)}
DELIVERY FAILURE SIGNAL: ${Boolean(reply.possible_delivery_failure)}
LATEST REPLY:
${reply.reply_text || ''}

RETURN EXACTLY
{
  "intent": "unclear",
  "confidence": 0,
  "summary": "",
  "human_review_required": true,
  "suggested_next_action": ""
}`;

return {
  json: {
    ...data,
    reply_classification_prompt: prompt
  }
};

const bases = $('Build Reply Classification Prompt').all(0, $runIndex);
const base = bases[$itemIndex]?.json || bases[0]?.json || {};
const current = $json || {};
const reply = base.incoming_reply || {};

const raw = current.output ?? current.text ?? current.content ?? '';
const rawText = typeof raw === 'string' ? raw : JSON.stringify(raw);
let parsed = {};
let parseError = '';

try {
  const cleaned = rawText.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  const match = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch (error) {
  parseError = error.message || 'invalid_ai_json';
}

const allowed = new Set([
  'meeting_request', 'pricing_question', 'interested', 'information_request',
  'not_interested', 'unsubscribe', 'out_of_office', 'wrong_person',
  'delivery_failed', 'unclear'
]);
const clean = (value, max = 2000) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const clamp = (value) => {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(0, Math.min(100, Math.round(number))) : 0;
};

const latest = clean(reply.reply_text, 8000).toLowerCase();
const subject = clean(reply.reply_subject, 500).toLowerCase();
const combined = `${subject}\n${latest}`;

let intent = clean(parsed.intent, 50).toLowerCase();
if (!allowed.has(intent)) intent = 'unclear';
let confidence = clamp(parsed.confidence);
let summary = clean(parsed.summary, 1000);
let humanReviewRequired = parsed.human_review_required !== false;
let suggestedNextAction = clean(parsed.suggested_next_action, 1000);

if (reply.possible_delivery_failure || /undeliverable|delivery (?:status notification|failure|failed)|mail delivery|returned mail|address not found|message blocked|bounced/i.test(combined)) {
  intent = 'delivery_failed';
  confidence = 100;
} else if (/unsubscribe|remove me|remove my email|stop (?:emailing|contacting)|do not contact|don't contact|no more emails|opt[ -]?out/i.test(combined)) {
  intent = 'unsubscribe';
  confidence = 100;
} else if (/not interested|no thanks|not a fit|we(?:'| a)re good|do not need|don't need|not looking/i.test(combined)) {
  intent = 'not_interested';
  confidence = Math.max(confidence, 95);
} else if (reply.possible_automated_reply || /out of office|automatic reply|auto.?reply|away from (?:the )?office|on leave|vacation/i.test(combined)) {
  intent = 'out_of_office';
  confidence = Math.max(confidence, 95);
} else if (/wrong person|not the right person|no longer work|left the company|wrong company/i.test(combined)) {
  intent = 'wrong_person';
  confidence = Math.max(confidence, 95);
} else if (/schedule|book (?:a )?(?:call|meeting)|calendar|availability|available (?:on|at)|set up (?:a )?(?:call|meeting)/i.test(combined)) {
  intent = 'meeting_request';
  confidence = Math.max(confidence, 90);
} else if (/pricing|price|cost|quote|rates?|budget|how much/i.test(combined)) {
  intent = 'pricing_question';
  confidence = Math.max(confidence, 90);
} else if (/interested|sounds good|tell me more|let(?:'| u)s talk|open to (?:a )?(?:call|chat)|please send/i.test(combined)) {
  intent = intent === 'unclear' ? 'interested' : intent;
  confidence = Math.max(confidence, 80);
}

if (parseError && intent === 'unclear') {
  confidence = 25;
  summary = summary || 'AI output could not be parsed and no deterministic intent signal was found.';
  suggestedNextAction = 'Manual review required.';
}

const reportSent = Boolean(base.audit_report_sent_at);
const videoRequested = /\b(video|demo|walkthrough|screen.?share|google meet|zoom)\b/i.test(latest);
const explicitReport = /\b(?:send|share|show|see|want|like)\b.*\b(?:report|audit|breakdown|findings|fixes)\b|\b(?:report|audit|breakdown)\b.*\b(?:please|send|share)\b/i.test(latest);
const shortYes = /^(?:yes|sure|sounds good|please send|send it|go ahead|ok(?:ay)?)[.!\s]*$/i.test(latest.trim());
const stopped = ['unsubscribe','not_interested','wrong_person','delivery_failed','out_of_office'].includes(intent);
let replyAction = 'none';
if (!stopped) {
 if (videoRequested || intent === 'meeting_request') replyAction = 'booking';
 else if (explicitReport) replyAction = 'report';
 else if (intent === 'interested' || shortYes) replyAction = reportSent ? 'booking' : 'report';
}
const meetingRequested = replyAction === 'booking';
const pricingQuestion = intent === 'pricing_question';
let finalStatus = 'reply_needs_review';
let nextWorkflow = '';
let doNotContact = false;
const nextFollowUpAt = null;
if (intent === 'unsubscribe' || intent === 'not_interested') {
 finalStatus = intent === 'unsubscribe' ? 'do_not_contact' : 'not_interested'; doNotContact = true; humanReviewRequired = false;
} else if (intent === 'delivery_failed' || intent === 'wrong_person') {
 finalStatus = intent === 'delivery_failed' ? 'email_bounced' : 'needs_contact_enrichment'; doNotContact = true; humanReviewRequired = true;
} else if (replyAction !== 'none') {
 finalStatus = replyAction === 'report' ? 'report_requested' : 'meeting_requested';
 nextWorkflow = '05 - Meeting Booking & Sales Handoff'; humanReviewRequired = false;
 suggestedNextAction = replyAction === 'report' ? 'Send verified report in the existing thread.' : 'Send 30-minute Calendly link for a Google Meet walkthrough.';
} else {
 finalStatus = intent === 'out_of_office' ? 'reply_needs_review' : 'reply_needs_human';
 humanReviewRequired = true;
}

if (base.do_not_contact === true) { doNotContact = true; finalStatus = 'do_not_contact'; nextWorkflow = ''; replyAction = 'none'; humanReviewRequired = false; }
return {
  json: {
    id: base.id,
    company_name: base.company_name || '',
    contact_name: base.contact_name || '',
    email: base.email || '',
    incoming_message_id: reply.incoming_message_id || '',
    gmail_thread_id: reply.gmail_thread_id || base.gmail_thread_id || '',
    from_email: reply.from_email || '',
    reply_subject: reply.reply_subject || '',
    reply_text: reply.reply_text || '',
    reply_received_at: reply.reply_received_at || new Date().toISOString(),
    reply_intent: intent,
    reply_confidence: confidence,
    reply_summary: summary,
    reply_action: replyAction,
    meeting_requested: meetingRequested,
    pricing_question: pricingQuestion,
    human_review_required: humanReviewRequired,
    suggested_next_action: suggestedNextAction,
    do_not_contact: doNotContact,
    final_status: finalStatus,
    final_next_workflow: nextWorkflow,
    next_follow_up_at: nextFollowUpAt,
    classification_error: parseError,
    reply_sender_match_type: base.reply_sender_match_type || '',
    ai_raw_output: rawText.slice(0, 10000)
  }
};

const result = $('Parse and Route Reply').all(0)[$itemIndex]?.json || {};
const update = $json || {};
const message = [
  update.error?.message,
  update.error?.description,
  update.errorMessage,
  update.description
].filter(Boolean).join(' | ');
const hasError = Boolean(
  update.error
  || update.errorMessage
  || (update.httpCode && Number(update.httpCode) >= 400)
  || (update.code && String(update.code).toLowerCase().startsWith('pgrst'))
);
return {
  json: {
    ...result,
    lead_update_ok: !hasError,
    lead_update_error: hasError ? (message || 'supabase_reply_update_failed').slice(0, 1500) : ''
  }
};

const lead = $json || {};
const clean = (value, max = 1000) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const previousOutreachAttempts = Math.max(0, Number(lead.outreach_attempts || 0));
const previousFollowUpCount = Math.max(0, Number(lead.follow_up_count || 0));
const email = clean(lead.email).toLowerCase();
const dueAt = lead.next_follow_up_at ? new Date(lead.next_follow_up_at).getTime() : 0;
const now = Date.now();
const doNotContact = lead.do_not_contact === true || String(lead.do_not_contact).toLowerCase() === 'true';
const emailValid = lead.email_validation_status === 'syntax_valid'
  && /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/i.test(email);

const marker = String(lead.last_outreach_error || '');
const previousGenerationAttempt = Number(marker.match(/follow_up_generation_attempt=(\d+)/)?.[1] || 0);
const generationAttempt = previousGenerationAttempt + 1;
const reasons = [];
if (doNotContact) reasons.push('do_not_contact');
if (lead.reply_received_at || lead.reply_status === 'received') reasons.push('reply_received_stop_follow_ups');
if (!emailValid) reasons.push('invalid_email');
if (!clean(lead.gmail_thread_id)) reasons.push('missing_gmail_thread_id');
if (!clean(lead.gmail_message_id)) reasons.push('missing_gmail_message_id');
if (previousOutreachAttempts < 1) reasons.push('initial_outreach_not_recorded');
if (previousFollowUpCount >= 3 || previousOutreachAttempts >= 4) reasons.push('maximum_follow_ups_reached');
if (!dueAt || dueAt > now) reasons.push('follow_up_not_due');

const nextAttempt = previousOutreachAttempts + 1;
const followUpNumber = previousFollowUpCount + 1;
const contactName = clean(lead.contact_name);
const outreachId = `followup-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;

return {
  json: {
    ...lead,
    email,
    outreach_id: outreachId,
    previous_outreach_attempts: previousOutreachAttempts,
    previous_follow_up_count: previousFollowUpCount,
    next_outreach_attempt: nextAttempt,
    follow_up_number: followUpNumber,
    follow_up_generation_attempt: generationAttempt,
    contact_first_name: contactName ? contactName.split(' ')[0] : '',
    follow_up_allowed: reasons.length === 0,
    follow_up_block_reason: reasons.join('; '),
    follow_up_context: {
      company_name: clean(lead.company_name),
      contact_name: contactName,
      contact_first_name: contactName ? contactName.split(' ')[0] : '',
      audit_findings: Array.isArray(lead.audit_findings) ? lead.audit_findings : [],
      original_subject: clean(lead.outreach_subject),
      original_email: clean(lead.outreach_body, 4000),
      primary_need: clean(lead.primary_need),
      recommended_service: clean(lead.recommended_service),
      reply_status: clean(lead.reply_status),
      follow_up_number: followUpNumber
    }
  }
};

const data = $json || {};
const context = data.follow_up_context || {};

const prompt = `Write follow-up number ${data.follow_up_number} in the existing Gmail thread for this CodeNativeX lead.

RULES
- Natural professional English.
- 40 to 90 words before the signature.
- This is a follow-up, so do not repeat the entire first email.
- Refer gently to the earlier note.
- Use only the supplied facts.
- Mention only the same main service.
- Use the first-touch plus Day 3 / Day 7 / Day 14 sequence. All emails stay in the same thread.
- Follow-up 1 (Day 3): a friendly reminder and ONE practical tip supported by audit_findings; no invented speed estimates.
- Follow-up 2 (Day 7): a useful verified recommendation. No case study or client results have been approved; do not invent any. Offer the free breakdown again.
- Follow-up 3 (Day 14): polite close, no guilt. Say the timing may not be right and they can reply later for the report.
- No attachments, booking links, video promises or call CTA in follow-ups. One low-pressure reply CTA only.
- Do not invent results, urgency, pricing, familiarity, audits, or website problems.
- No emojis, hype, guilt, manipulation, or multiple questions.
- Do not add a subject, signature, website URL, or opt-out line.
- Return strict JSON only.

CONTEXT
${JSON.stringify(context, null, 2)}

RETURN EXACTLY
{
  "body": "",
  "service_focus": "",
  "cta": ""
}`;

return {
  json: {
    ...data,
    follow_up_prompt: prompt
  }
};

const promptItems = $('Build Follow-Up Prompt').all(0, $runIndex);
const base = promptItems[$itemIndex]?.json || promptItems[0]?.json || {};
const current = $json || {};

const raw = current.output ?? current.text ?? current.content ?? '';
const rawText = typeof raw === 'string' ? raw : JSON.stringify(raw);
let parsed = {};
let parseError = '';

try {
  const cleaned = rawText
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '');
  const match = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch (error) {
  parseError = error.message || 'invalid_ai_json';
}

const body = String(parsed.body ?? '')
  .replace(/\r/g, '')
  .split('\n')
  .map((line) => line.replace(/[ \t]+/g, ' ').trim())
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 2000);

const wordCount = body ? body.split(/\s+/).filter(Boolean).length : 0;
const problems = [];
if (parseError) problems.push('ai_json_parse_failed');
if (!body) problems.push('missing_body');
if (wordCount < 30 || wordCount > 110) problems.push('invalid_word_count');
if (/\[[^\]]+\]|\{\{?[^}]+\}?\}/.test(body)) problems.push('unresolved_placeholder');
if (/guaranteed|100%|double your|triple your|risk[- ]free|act now/i.test(body)) problems.push('prohibited_claim');
if (current.error || current.errorMessage) problems.push('model_error');

if (/attach(?:ed|ment)|https?:\/\/|calendly|\d+[- ]minute call|\bvideo\b|\d+(?:\.\d+)?\s*%|we recently worked|our client/i.test(body)) problems.push('unapproved_follow_up_content');
const contentValid = problems.length === 0;
const signature = 'Best,\nCodeNativeX Team\nhttps://codenativex.com';
const optOut = 'If this is not relevant, reply "not interested" and we will not follow up.';
const finalBody = contentValid ? `${body}\n\n${signature}\n\n${optOut}` : '';

return {
  json: {
    ...base,
    follow_up_body: finalBody,
    follow_up_body_without_signature: body,
    follow_up_word_count: wordCount,
    follow_up_content_valid: contentValid,
    follow_up_generation_error: problems.join('; '),
    service_focus_used: String(parsed.service_focus ?? '').replace(/\s+/g, ' ').trim().slice(0, 300),
    ai_raw_output: rawText.slice(0, 10000)
  }
};

const sent = $json || {};
const confirmedItems = $('Restore Confirmed Follow-Up').all(0, $runIndex).map((item) => item.json || {});
const base = confirmedItems.find((item) => item.gmail_thread_id && item.gmail_thread_id === sent.threadId)
  || confirmedItems[$itemIndex]
  || {};
const errorMessage = [sent.error?.message, sent.error?.description, sent.errorMessage, sent.description]
  .filter(Boolean).join(' | ');
const hasError = Boolean(!String(sent.id || sent.messageId || '') || sent.error || sent.errorMessage || (sent.httpCode && Number(sent.httpCode) >= 400));
const sentAt = new Date();
const isFinalFollowUp = Number(base.follow_up_number) >= 3 || Number(base.next_outreach_attempt) >= 4;
const nextFollowUpAt = isFinalFollowUp
  ? null
  : new Date(Math.max(Date.parse(base.first_outreach_at || base.last_outreach_at || sentAt.toISOString()) + ([2,6,13][Number(base.follow_up_number)] || 13) * 86400000, sentAt.getTime() + 86400000)).toISOString();

return {
  json: {
    ...base,
    follow_up_outcome: hasError ? 'follow_up_send_failed' : 'follow_up_sent',
    final_status: hasError ? 'follow_up_failed' : (isFinalFollowUp ? 'no_response' : 'awaiting_reply'),
    final_outreach_status: hasError ? 'failed' : `follow_up_${base.follow_up_number}_sent`,
    latest_gmail_message_id: hasError ? base.gmail_message_id : String(sent.id || sent.messageId || base.gmail_message_id || ''),
    latest_gmail_thread_id: String(sent.threadId || base.gmail_thread_id || ''),
    last_follow_up_at: hasError ? null : sentAt.toISOString(),
    next_follow_up_at: hasError ? null : nextFollowUpAt,
    final_next_workflow: hasError ? '' : (isFinalFollowUp ? '' : '04 - Reply Monitoring & Follow-Up'),
    final_error: hasError ? (errorMessage || 'gmail_follow_up_send_failed_ambiguous_do_not_retry') : ''
  }
};

const base = $json || {};
const retryable = Number(base.follow_up_generation_attempt || 1) < 3;
return {
  json: {
    ...base,
    follow_up_outcome: retryable ? 'follow_up_generation_retry_scheduled' : 'follow_up_generation_failed',
    final_status: retryable ? 'awaiting_reply' : 'follow_up_failed',
    final_outreach_status: retryable ? 'follow_up_generation_retry' : 'failed',
    next_outreach_attempt: retryable ? Number(base.previous_outreach_attempts || 0) : Number(base.next_outreach_attempt || 0),
    follow_up_number: retryable ? Number(base.previous_follow_up_count || 0) : Number(base.follow_up_number || 0),
    latest_gmail_message_id: base.gmail_message_id || '',
    latest_gmail_thread_id: base.gmail_thread_id || '',
    last_follow_up_at: null,
    next_follow_up_at: retryable ? new Date(Date.now() + (60 * 60 * 1000)).toISOString() : null,
    final_next_workflow: retryable ? '04 - Reply Monitoring & Follow-Up' : '',
    final_error: `follow_up_generation_attempt=${base.follow_up_generation_attempt || 1}; ${base.follow_up_generation_error || 'follow_up_generation_failed'}`
  }
};

const base = $json || {};
const reason = String(base.follow_up_block_reason || base.follow_up_claim_error || 'follow_up_not_allowed');
const maximumReached = reason.includes('maximum_follow_ups_reached');
const stopped = reason.includes('do_not_contact');
const claimFailed = !base.follow_up_claim_ok;
return {
  json: {
    ...base,
    follow_up_body: '',
    follow_up_outcome: claimFailed ? 'follow_up_claim_failed' : 'follow_up_blocked',
    final_status: stopped ? 'do_not_contact' : (maximumReached ? 'no_response' : 'follow_up_failed'),
    final_outreach_status: stopped ? 'stopped' : (maximumReached ? 'follow_up_complete' : 'failed'),
    next_outreach_attempt: Number(base.previous_outreach_attempts || 0),
    follow_up_number: Number(base.previous_follow_up_count || 0),
    latest_gmail_message_id: base.gmail_message_id || '',
    latest_gmail_thread_id: base.gmail_thread_id || '',
    last_follow_up_at: null,
    next_follow_up_at: null,
    final_next_workflow: '',
    final_error: reason
  }
};

const result = $('Finalize Follow-Up Outcome').all(0, $runIndex)[$itemIndex]?.json || {};
const update = $json || {};
const message = [
  update.error?.message,
  update.error?.description,
  update.errorMessage,
  update.description
].filter(Boolean).join(' | ');
const hasError = Boolean(
  update.error
  || update.errorMessage
  || (update.httpCode && Number(update.httpCode) >= 400)
  || (update.code && String(update.code).toLowerCase().startsWith('pgrst'))
);
return {
  json: {
    ...result,
    lead_update_ok: !hasError,
    lead_update_error: hasError ? (message || 'supabase_follow_up_update_failed').slice(0, 1500) : ''
  }
};

const result = $('Restore Follow-Up Result').all(0, $runIndex)[$itemIndex]?.json || {};
const event = $json || {};
const eventError = event.error?.message || event.errorMessage || '';
return {
  json: {
    event_type: 'lead_follow_up_completed',
    lead_id: result.id || '',
    outreach_id: result.outreach_id || '',
    company_name: result.company_name || '',
    recipient_email: result.email || '',
    follow_up_number: result.follow_up_number || 0,
    total_outreach_attempts: result.next_outreach_attempt || 0,
    outcome: result.follow_up_outcome || '',
    status: result.final_status || '',
    outreach_status: result.final_outreach_status || '',
    gmail_message_id: result.latest_gmail_message_id || '',
    gmail_thread_id: result.latest_gmail_thread_id || '',
    next_follow_up_at: result.next_follow_up_at || null,
    next_workflow: result.final_next_workflow || '',
    lead_updated: Boolean(result.lead_update_ok),
    lead_update_error: result.lead_update_error || '',
    event_logged: !eventError,
    event_log_error: eventError,
    completed_at: result.completed_at || new Date().toISOString()
  }
};

const combinedItems = $('Combine Reply with Lead').all(0, $runIndex);
const base = combinedItems[$itemIndex]?.json || combinedItems[0]?.json || {};
const reply = base.incoming_reply || {};
const existing = $json || {};

const normalizeEmail = (value) => String(value || '').trim().toLowerCase();
const domainOf = (email) => email.includes('@') ? email.split('@').pop() : '';
const freeDomains = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'outlook.com', 'hotmail.com',
  'live.com', 'icloud.com', 'aol.com', 'proton.me', 'protonmail.com'
]);

const fromEmail = normalizeEmail(reply.from_email);
const expectedEmail = normalizeEmail(base.email);
const fromDomain = domainOf(fromEmail);
const expectedDomain = domainOf(expectedEmail);
const exactSender = Boolean(fromEmail && expectedEmail && fromEmail === expectedEmail);
const sameBusinessDomain = Boolean(
  fromDomain
  && expectedDomain
  && fromDomain === expectedDomain
  && !freeDomains.has(expectedDomain)
);
const automated = Boolean(reply.possible_automated_reply || reply.possible_delivery_failure);
const senderAccepted = exactSender || sameBusinessDomain || automated;
const duplicate = Boolean(existing.id || existing.incoming_message_id);
const duplicateCheckFailed = Boolean(
  existing.error
  || existing.errorMessage
  || (existing.httpCode && Number(existing.httpCode) >= 400)
);

const reasons = [];
if (!base.id) reasons.push('lead_not_found_for_thread');
if (!reply.incoming_message_id) reasons.push('missing_message_id');
if (!reply.gmail_thread_id) reasons.push('missing_thread_id');
if (!senderAccepted) reasons.push('sender_does_not_match_lead');
if (!reply.reply_text && !reply.reply_subject) reasons.push('empty_reply');
if (duplicate) reasons.push('duplicate_message_already_processed');
if (duplicateCheckFailed) reasons.push('duplicate_check_failed');

return {
  json: {
    ...base,
    reply_gate_passed: reasons.length === 0,
    reply_gate_reason: reasons.join('; '),
    reply_duplicate: duplicate,
    reply_sender_match: senderAccepted,
    reply_sender_match_type: exactSender
      ? 'exact_email'
      : (sameBusinessDomain ? 'same_business_domain' : (automated ? 'automated_system_message' : 'none'))
  }
};

return {
  json: {
    event_type: 'incoming_reply_ignored',
    lead_id: $json.id || '',
    company_name: $json.company_name || '',
    incoming_message_id: $json.incoming_reply?.incoming_message_id || '',
    gmail_thread_id: $json.incoming_reply?.gmail_thread_id || '',
    from_email: $json.incoming_reply?.from_email || '',
    duplicate: Boolean($json.reply_duplicate),
    sender_match: Boolean($json.reply_sender_match),
    reason: $json.reply_gate_reason || 'reply_gate_failed',
    side_effects_performed: false,
    completed_at: new Date().toISOString()
  }
};

const claim = $json || {};
const preparedItems = $('Prepare Follow-Up Claim').all(0, $runIndex).map((item) => item.json || {});
const prepared = preparedItems.find((item) => item.id && item.id === claim.id)
  || preparedItems[$itemIndex]
  || {};
const message = [claim.error?.message, claim.error?.description, claim.errorMessage, claim.description]
  .filter(Boolean).join(' | ');
const hasError = Boolean(claim.error || claim.errorMessage || (claim.httpCode && Number(claim.httpCode) >= 400));

return {
  json: {
    ...prepared,
    follow_up_claim_ok: !hasError && Boolean(claim.id),
    follow_up_claim_error: hasError ? (message || 'follow_up_claim_failed').slice(0, 1500) : ''
  }
};

const confirmed = $json || {};
const guardedItems = $('Parse and Guard Follow-Up').all(0, $runIndex).map((item) => item.json || {});
const base = guardedItems.find((item) => item.id && item.id === confirmed.id)
  || guardedItems[$itemIndex]
  || {};
return { json: { ...base, follow_up_rechecked: Boolean(confirmed.id) } };

const cutoff = Date.now() - (20 * 60 * 1000);
return $input.all()
  .map((item) => item.json || {})
  .filter((row) => {
    const updated = new Date(row.updated_at || row.last_outreach_at || 0).getTime();
    return Number.isFinite(updated) && updated > 0 && updated <= cutoff;
  })
  .map((row) => ({ json: row }));

const value = $json || {};
return {
  json: {
    ...value,
    follow_up_body: '',
    follow_up_outcome: 'stale_follow_up_claim_stopped',
    final_status: 'follow_up_failed',
    final_outreach_status: 'failed',
    next_outreach_attempt: Number(value.outreach_attempts || 0),
    follow_up_number: Number(value.follow_up_count || 0),
    latest_gmail_message_id: value.gmail_message_id || '',
    latest_gmail_thread_id: value.gmail_thread_id || '',
    last_follow_up_at: null,
    next_follow_up_at: null,
    final_next_workflow: '',
    final_error: 'stale_follow_up_claim_recovered_manual_review_required'
  }
};

const jobItems = $('Activate Reply Monitoring Job').all(0, $runIndex);
const job = jobItems[0]?.json || {};
const keys = [...new Set($input.all()
  .map((item) => String(item.json?.lead_key || '').trim())
  .filter(Boolean))];
return keys.map((leadKey) => ({ json: { job, lead_key: leadKey } }));

const jobItems = $('Activate Reply Monitoring Job').all(0, $runIndex);
const job = jobItems[0]?.json || {};
const leads = $input.all().map((item) => item.json || {});
const targetStatuses = new Set([
  'awaiting_reply', 'follow_up_preparing', 'meeting_requested', 'reply_needs_human',
  'do_not_contact', 'not_interested', 'no_response', 'email_bounced',
  'follow_up_failed', 'reply_needs_review', 'needs_contact_enrichment'
]);
const targets = leads.filter((lead) => Boolean(lead.outreach_id) || targetStatuses.has(String(lead.status || '')));
const positive = targets.filter((lead) =>
  ['meeting_requested', 'reply_needs_human'].includes(String(lead.status || ''))
  || lead.next_workflow === '05 - Meeting Booking & Sales Handoff'
);
const active = targets.filter((lead) =>
  ['awaiting_reply', 'follow_up_preparing'].includes(String(lead.status || ''))
  && lead.next_workflow === '04 - Reply Monitoring & Follow-Up'
);
const terminal = targets.filter((lead) => !active.some((entry) => entry.id === lead.id));
const transitionReady = positive.length > 0 || (targets.length > 0 && active.length === 0);

return [{
  json: {
    ...job,
    reply_monitoring_transition_ready: transitionReady,
    reply_monitoring_summary: {
      matched_leads: leads.length,
      outreach_targets: targets.length,
      awaiting_reply: active.length,
      positive_replies: positive.length,
      terminal_targets: terminal.length,
      meeting_requests: positive.filter((lead) => lead.status === 'meeting_requested').length,
      human_reply_queue: positive.filter((lead) => lead.status === 'reply_needs_human').length
    }
  }
}];

const job = $json || {};
const summary = job.reply_monitoring_summary || {};
const hasPositiveReply = Number(summary.positive_replies || 0) > 0;
const completedAt = hasPositiveReply ? null : new Date().toISOString();
const status = hasPositiveReply ? 'queued' : 'completed';
const stage = hasPositiveReply ? 'sales_handoff_queued' : 'reply_monitoring_completed';
const nextWorkflow = hasPositiveReply ? '05 - Meeting Booking & Sales Handoff' : '';
const progress = hasPositiveReply ? 80 : 100;
const eventType = hasPositiveReply ? 'sales_handoff_queued' : 'reply_monitoring_completed';
const message = hasPositiveReply
  ? `Reply monitoring found ${summary.positive_replies || 0} positive reply/replies and queued Workflow 05.`
  : 'Reply monitoring reached a terminal state with no sales handoff required.';

return {
  json: {
    ...job,
    outcome_status: status,
    outcome_stage: stage,
    outcome_progress: progress,
    outcome_next_workflow: nextWorkflow,
    outcome_completed_at: completedAt,
    event_type: eventType,
    event_status: status,
    event_stage: stage,
    event_severity: hasPositiveReply ? 'info' : 'warning',
    event_message: message,
    merged_result_summary: {
      ...(job.result_summary || {}),
      reply_monitoring: summary
    }
  }
};

const update = $json || {};
const preparedItems = $('Prepare Reply Job Outcome').all(0, $runIndex).map((item) => item.json || {});
const prepared = preparedItems.find((item) => item.job_id && item.job_id === update.job_id)
  || preparedItems[$itemIndex]
  || {};
const error = [update.error?.message, update.error?.description, update.errorMessage]
  .filter(Boolean).join(' | ');
return { json: { ...prepared, job_update_ok: !error && Boolean(update.job_id), job_update_error: error } };
